//Write a program to print even numbers from range 1 to 20 using for loop.
package Practice;

public class evenfrom1to20 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for(int i = 1 ; i<= 20; i++) {
			if(i % 2 == 0 ) {
				System.out.println(i);
			}
		}

	}

}
